 static int checks;static void Yes(bool b,string why){checks++;if(!b)throw new Exception(why);}static void Reject(Action a,string why){bool bad=false;try{a();}catch{bad=true;}Yes(bad,why);}
 static byte[] Json<T>(T o){using(var m=new MemoryStream()){new DataContractJsonSerializer(typeof(T)).WriteObject(m,o);return m.ToArray();}}
 static MarkerSnapshot Raw(){var p=new MarkerPlan("original-synthetic-fixture","markers");p.Set(MarkerKind.Start,new MarkerPose{AtMs=1,Position=new MarkerPoint(0,0,1)});p.Set(MarkerKind.Finish,new MarkerPose{AtMs=2,Position=new MarkerPoint(100,0,1)});return p.Set(MarkerKind.Listener,new MarkerPose{AtMs=3,Position=new MarkerPoint(40,20,5),OnFoot=true});}
 static MarkerSet Markers(){var b=Json(Raw());return MarkerSet.Parse(b,Check.Hash(b),3,"markers","original-synthetic-fixture");}
 static Pose P(StopKind k){return new Pose{Position=new MarkerPoint(k==StopKind.Finish?100:k==StopKind.Start?0:(int)k*20,0,1),Forward=new MarkerPoint(1,0,0),AtMs=100+(int)k*10000,Player=42,Generation=1,OnFoot=true};}
 static GeometryObservation O(Ray ray,Pose p,bool miss=false){return new GeometryObservation{SessionId="survey",GameVersion="1.0.1158.16",FrameworkVersion="1.132.1428.17748",Origin=ray.Origin,End=ray.End,MaximumDistance=Point3.Sub(ray.End,ray.Origin).Length,ObservedAtMs=p.AtMs+1,TraceDurationMs=.01,ConversionDurationMs=.01,TraceCalls=1,IgnoredPlayerHandle=p.Player,PlayerSpeed=0,SetupStatus="on_foot_stationary_by_SDK_getters",QueryProvenance=ray.Role=="ground-probe"?"airport-ground-probe-v1":"airport-body-line-v1",Completion=miss?"miss":"hit",PositionStatus=miss?"not_returned_miss":"observed",NormalStatus=miss?"not_returned_miss":"observed",EntityStatus=miss?"not_returned_miss":"none_returned_static_unproven",HitPosition=miss?(Point3?)null:new Point3(ray.Origin.X,ray.Origin.Y,0),HitNormal=miss?(Point3?)null:new Point3(0,0,1)};}
 static StopRecord Group(Survey s,StopKind k,Action<int,GeometryObservation> change=null){var p=P(k);s.Begin(k,p);int count=SurveyPlan.Ground(k,p.Position,p.Forward).Length;for(int i=0;i<count;i++){var ray=s.ClaimRay(p);var o=O(ray,p,ray.Role!="ground-probe");if(change!=null)change(i,o);s.Accept(o);if(k==StopKind.Start&&i==8&&s.Snapshot().Stops[0].SkippedCalls==0)count=12;}return s.Complete(new Navigation{Calls=2,NodesLoaded=true,TravelEstimate=100},new Interference{Enumerations=3,AtMs=p.AtMs+2},p.AtMs+3);}
 public static int Main(string[] args)
 {
  string dir=args[0];Directory.CreateDirectory(dir);var marker=Markers();var bytes=Json(Raw());
