  Reject(()=>MarkerSet.Parse(bytes,new string('0',64),3,"markers","original-synthetic-fixture"),"fingerprint mismatch");Reject(()=>MarkerSet.Parse(new byte[]{0},Check.Hash(new byte[]{0}),3,"markers","original-synthetic-fixture"),"corrupt JSON");
  var s=new Survey(marker,"survey");var start=Group(s,StopKind.Start);Yes(start.ActualCalls==12&&start.Plan.Count==12,"9 ground + 3 lines");Yes(start.Surface=="PARTIAL_SAMPLED_SUPPORT"&&start.BodyClearance=="PARTIAL_LINES_ONLY_NOT_BODY_VOLUME","flat is partial, lines not body volume");Yes(start.ProposedSupportPoint.Value.Z==0&&s.Snapshot().OriginalStart.Z==1,"candidate never replaces seated height");
  foreach(StopKind k in new[]{StopKind.Mid1,StopKind.Mid2,StopKind.Mid3,StopKind.Finish,StopKind.Runout})Group(s,k);
  var result=s.Snapshot();Yes(s.Calls==36&&result.Stops.Length==6&&result.IntermediatePoints==3,"exact fixed budget/order");Yes(!result.RouteClear&&!result.BenchmarkStartSupported&&result.RouteContinuity=="UNKNOWN"&&result.StoppingDistance=="UNKNOWN","point observations never certify route or stopping");Yes(result.OriginalStart.Z==1&&result.OriginalFinish.X==100&&result.OriginalListener.Z==5&&result.MarkerFingerprint==marker.Fingerprint,"all historical markers and fingerprint preserved");Yes(result.Stops.All(x=>x.CandidateOnly&&!x.ReplacesOriginalMarker&&x.Coverage=="PARTIAL"),"unknown gaps remain");Reject(()=>s.Begin(StopKind.Runout,P(StopKind.Runout)),"no repeat");Reject(()=>s.ClaimRay(P(StopKind.Start)),"budget exhausted");
  SurveyPersistence.Save(Path.Combine(dir,"survey.json"),result);Reject(()=>SurveyPersistence.Save(Path.Combine(dir,"survey.json"),result),"no overwrite");Reject(()=>SurveyPersistence.Save(Path.GetFullPath("public.json"),result),"private path");Reject(()=>PrivateFiles.RequireLocal(@"\\host\share\.local\x"),"no network path");
  result.Stops[0].Player.Position=new MarkerPoint(888,0,0);Yes(s.Snapshot().Stops[0].Player.Position.X==0,"snapshot isolation");
  foreach(string mode in new[]{"hole","slope","uneven","normal","body"}){var q=new Survey(marker,"survey");var r=Group(q,StopKind.Start,(i,o)=>{if(mode=="hole"&&i==4){o.Completion="miss";o.HitPosition=null;o.HitNormal=null;o.PositionStatus=o.NormalStatus=o.EntityStatus="not_returned_miss";}if(mode=="slope"&&i<9)o.HitNormal=new Point3(.5,0,Math.Sqrt(.75));if(mode=="uneven"&&i==0)o.HitPosition=new Point3(o.Origin.Value.X,o.Origin.Value.Y,.3);if(mode=="normal"&&i==0)o.HitNormal=new Point3(0,0,-1);if(mode=="body"&&i==9){o.Completion="hit";o.HitPosition=new Point3((o.Origin.Value.X+o.End.Value.X)/2,(o.Origin.Value.Y+o.End.Value.Y)/2,o.Origin.Value.Z);o.HitNormal=new Point3(0,1,0);o.PositionStatus=o.NormalStatus="observed";o.EntityStatus="none_returned_static_unproven";}});
   if(mode=="hole")Yes(r.ActualCalls==9&&r.SkippedCalls==3&&r.Surface=="UNKNOWN_MISSING_SUPPORT","missing support skips dependent probes without reallocation");else if(mode=="body")Yes(r.BodyClearance=="OBSTRUCTION_ON_PROBED_LINE","line obstruction");else Yes(r.Surface=="UNSUITABLE_FOR_DECLARED_FLAT_SCREEN","slope/height/inconsistent normal conservative rejection");}
  foreach(string mode in new[]{"order","moving","vehicle","interior","identity","far","timeout","invalidhit","unfinished","aux"}){var q=new Survey(marker,"survey");var p=P(StopKind.Start);if(mode=="order"){Reject(()=>q.Begin(StopKind.Mid1,p),mode);continue;}if(mode=="vehicle")p.OnFoot=false;if(mode=="interior")p.Interior=1;if(mode=="far")p.Position=new MarkerPoint(10,0,1);if(mode=="vehicle"||mode=="interior"||mode=="far"){Reject(()=>q.Begin(StopKind.Start,p),mode);Yes(q.Terminal,"invalid setup closed");continue;}q.Begin(StopKind.Start,p);
   if(mode=="unfinished"||mode=="aux"){if(mode=="aux"){for(int i=0;i<12;i++){var ray=q.ClaimRay(p);q.Accept(O(ray,p,i>=9));}}Reject(()=>q.Complete(new Navigation{Calls=3},new Interference(),p.AtMs+1),mode);}
   else if(mode=="invalidhit"){var ray=q.ClaimRay(p);var o=O(ray,p);o.HitNormal=new Point3();Reject(()=>q.Accept(o),mode);}else{if(mode=="moving")p.Position=new MarkerPoint(.1,0,1);if(mode=="identity")p.Generation++;if(mode=="timeout")p.AtMs+=2501;Reject(()=>q.ClaimRay(p),mode);}Yes(q.Terminal,"failure terminal, cannot retry");Reject(()=>q.ClaimRay(P(StopKind.Start)),"cannot consume another query after failure");}
  foreach(bool future in new[]{true,false}){var q=new Survey(marker,"survey");var p=P(StopKind.Start);q.Begin(StopKind.Start,p);for(int i=0;i<12;i++){var ray=q.ClaimRay(p);q.Accept(O(ray,p,i>=9));}Reject(()=>q.Complete(new Navigation(),new Interference{AtMs=p.AtMs,FutureClearance=future,Coverage=future?"PARTIAL_STREAMED_POOL":"VERIFIED"},p.AtMs+1),"forged clearance/coverage rejected");Yes(q.Terminal,"forged evidence closes survey");}
  var dimensions=new Survey(marker,"survey");Reject(()=>dimensions.SetDimensions(new Dimensions{Status="OBSERVED_MODEL_BOUNDS",Minimum=new MarkerPoint(),Maximum=new MarkerPoint(-1,1,1)}),"invalid model bounds");dimensions.SetDimensions(new Dimensions());Reject(()=>dimensions.SetDimensions(new Dimensions()),"one dimension record only");
  Yes(SurveyPlan.ClassifyNavigation(new Navigation{NodesLoaded=true,TravelEstimate=20})=="NAVIGATION_ESTIMATE_CANDIDATE_ONLY","finite nav estimate is not AI proof");foreach(var n in new[]{new Navigation(),new Navigation{NodesLoaded=false,TravelEstimate=20},new Navigation{NodesLoaded=true,TravelEstimate=100000},new Navigation{NodesLoaded=true,TravelEstimate=double.NaN},new Navigation{Error="call failed"}})Yes(SurveyPlan.ClassifyNavigation(n)=="UNKNOWN","unloaded/sentinel/failure never invented route");
  foreach(string kind in new[]{"vehicle","ped","object"})Yes(SurveyPlan.ClassifyInterference(new Interference{AtMs=10,Nearby=new[]{new Occupant{Kind=kind,Velocity=new MarkerPoint(1,0,0)}}},11)=="POTENTIAL_OBSTRUCTION_IN_LOCAL_SCOPE","local obstruction kind");Yes(SurveyPlan.ClassifyInterference(new Interference{AtMs=1},2002)=="UNKNOWN","stale observation");Yes(SurveyPlan.ClassifyInterference(new Interference{AtMs=1,Error="partial"},2)=="UNKNOWN","failed enumeration");Yes(SurveyPlan.ClassifyInterference(new Interference{AtMs=1,Omitted=100},2)=="PARTIALLY_OBSERVED_NO_OCCUPANCY_RETURNED","omissions cannot prove clear");
  var id=new Identity{Handle=1,Model=2,Generation=1,Session="s",Creation="owned"};var reused=id;reused.Generation++;
  Yes(CleanupReview.Assess(id,reused,false,false,false,false).StartsWith("AMBIGUOUS"),"reuse blocks mutation");Yes(CleanupReview.Assess(id,null,false,false,true,false)=="UNKNOWN_INCOMPLETE_POOL","pool absence not proof");Yes(CleanupReview.Assess(id,null,false,false,false,false)=="UNKNOWN_RUNTIME_ABSENCE_NOT_PROVEN","native absent alone not generation proof");Yes(CleanupReview.Assess(id,null,false,true,false,false)=="CONTRADICTORY_NO_MUTATION","contradiction");Yes(CleanupReview.Assess(id,null,false,false,false,true).StartsWith("ABSENT_IN_ORIGINAL_SYNTHETIC"),"only synthetic registry authoritative");
  var watch=Stopwatch.StartNew();for(int i=0;i<50;i++){var q=new Survey(Markers(),"survey");Group(q,StopKind.Start);}double validation=watch.Elapsed.TotalMilliseconds;watch.Restart();for(int i=0;i<100;i++)s.Snapshot();double snapshots=watch.Elapsed.TotalMilliseconds;watch.Restart();for(int i=0;i<100;i++)SurveyPlan.ClassifyInterference(new Interference{AtMs=1},2);double obstruction=watch.Elapsed.TotalMilliseconds;watch.Restart();for(int i=0;i<10;i++)SurveyPersistence.Save(Path.Combine(dir,"persist-"+i+".json"),s.Snapshot());double persistence=watch.Elapsed.TotalMilliseconds;
  File.WriteAllText(Path.Combine(dir,"performance.json"),"{\"domain\":\"original-synthetic-fixture\",\"setupAndSurface50Ms\":"+validation.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+",\"snapshots100Ms\":"+snapshots.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+",\"obstruction100Ms\":"+obstruction.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+",\"persistence10Ms\":"+persistence.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+",\"bytes\":"+new FileInfo(Path.Combine(dir,"survey.json")).Length+",\"managedBytes\":"+GC.GetTotalMemory(false)+",\"privateBytes\":"+Process.GetCurrentProcess().PrivateMemorySize64+"}");
  Console.WriteLine("PASS: "+checks+" original airport survey assertions; no SDK/game execution.");return 0;
